# This file is generated by rsscipy's build process (`tools/build_rust.py`).
# It replaces the meson-generated `scipy/__config__.py`: the compiled layer is
# now Rust, so the build reports the Rust toolchain instead of C/Cython/pythran.
from enum import Enum

import platform as _platform
import sys as _sys

__all__ = ["show"]

_built_with_meson = False


class DisplayModes(Enum):
    stdout = "stdout"
    dicts = "dicts"


def _cleanup(d):
    """Remove empty values in a `dict` recursively."""
    if isinstance(d, dict):
        return {k: _cleanup(v) for k, v in d.items() if v != '' and _cleanup(v) != ''}
    return d


def _rust_toolchain():
    import json
    import subprocess
    try:
        out = subprocess.run(
            ["rustc", "--version", "--verbose"],
            capture_output=True, text=True, timeout=30,
        ).stdout
        info = {}
        for line in out.splitlines()[1:]:
            if ":" in line:
                k, _, v = line.partition(":")
                info[k.strip()] = v.strip()
        return {
            "name": "rustc",
            "version": info.get("release", ""),
            "host": info.get("host", ""),
        }
    except Exception:
        return {"name": "rustc", "version": "", "host": ""}


def _backend_version(name):
    try:
        mod = __import__(name)
        return getattr(mod, "__version__", "")
    except Exception:
        return ""


CONFIG = _cleanup(
    {
        "Compilers": {
            "rust": _rust_toolchain(),
        },
        "Machine Information": {
            "host": {
                "cpu": _platform.machine(),
                "family": _platform.system(),
            },
        },
        "Build Dependencies": {
            "rsnumpy": {
                "name": "rsnumpy",
                "version": _backend_version("rsnumpy"),
                "detection method": "pkgconfig",
            },
            "pyo3": {
                "name": "pyo3",
                "version": "0.29",
                "detection method": "cargo",
            },
            # No BLAS/LAPACK backend is wired up yet: the Rust port of
            # `scipy.linalg` will plug one in (see `rust/`).  Declaring the keys
            # keeps `scipy.linalg.blas` importable in the meantime.
            "blas": {
                "name": "unknown",
                "found": False,
                "version": "",
                "detection method": "",
                "has ilp64": False,
                "cython blas ilp64": False,
            },
            "lapack": {
                "name": "unknown",
                "found": False,
                "version": "",
                "detection method": "",
                "has ilp64": False,
            },
        },
        "Python Information": {
            "path": _sys.executable,
            "version": _sys.version.split()[0],
        },
    }
)


def _check_pyyaml():
    import yaml

    return yaml


def show(mode=DisplayModes.stdout.value):
    """Show the libraries and system information rsscipy was built with."""
    if mode == DisplayModes.stdout.value:
        try:  # Non-standard library, check import
            yaml = _check_pyyaml()

            print(yaml.dump(CONFIG))
        except ModuleNotFoundError:
            import json
            import warnings

            warnings.warn("Install `pyyaml` for better output", stacklevel=1)
            print(json.dumps(CONFIG, indent=2))
    elif mode == DisplayModes.dicts.value:
        return CONFIG
    else:
        raise AttributeError(
            f"Invalid `mode`, use one of: {', '.join([e.value for e in DisplayModes])}"
        )
